export function motionAt(u,time,{amplitude=.045,period=2.1666667461395264}={}){
  const tailness=clamp(1-u,0,1.16),omega=2*Math.PI/Math.max(.25,period),phase=omega*time-1.18*tailness;
  const envelope=.015+.985*Math.pow(tailness,2.65);
  const lateral=amplitude*envelope*Math.sin(phase);
  const dEnvelope=-2.65*Math.pow(Math.max(tailness,1e-5),1.65);
  const slope=amplitude*(-dEnvelope*Math.sin(phase)+1.18*envelope*Math.cos(phase));
  return {lateral,yaw:Math.atan(slope),phase,envelope};
}

export function finletMotion(index,time,{period=2.1666667461395264,side=1}={}){
  const omega=2*Math.PI/period,phase=omega*time-index*.24+(side<0?Math.PI:.0);
  return {pitch:.055*Math.sin(phase),heave:.0035*Math.sin(phase-.45)};
}
